<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\Event;use Illuminate\Http\Request;use Illuminate\Support\{Str,Facades\Storage};
class EventController extends Controller{public function index(){return view('admin.events.index',['items'=>Event::latest('starts_at')->paginate(20)]);}public function create(){return view('admin.events.form',['item'=>new Event]);}public function store(Request $r){Event::create($this->data($r));return redirect()->route('admin.events.index')->with('ok','Событие создано');}public function edit(Event $event){return view('admin.events.form',['item'=>$event]);}public function update(Request $r,Event $event){$old=$event->cover;$d=$this->data($r,$event);$event->update($d);if(isset($d['cover'])&&$old&&$old!==$d['cover'])Storage::disk('public')->delete($old);return redirect()->route('admin.events.index')->with('ok','Событие обновлено');}public function destroy(Event $event){if($event->cover)Storage::disk('public')->delete($event->cover);$event->delete();return back();}private function data(Request $r,?Event $item=null):array{$d=$r->validate(['title'=>'required|max:255','description'=>'nullable','place'=>'nullable|max:255','starts_at'=>'required|date','ends_at'=>'nullable|date|after_or_equal:starts_at','cover'=>'nullable|image|max:10240']);$d['slug']=$this->slug($r->input('slug')?:$d['title'],$item?->id);if($r->hasFile('cover'))$d['cover']=$r->file('cover')->store('events','public');$d['is_published']=$r->boolean('is_published');return $d;}private function slug($v,$ignore=null){$base=Str::slug($v)?:'event';$s=$base;$i=2;while(Event::where('slug',$s)->when($ignore,fn($q)=>$q->where('id','!=',$ignore))->exists())$s=$base.'-'.$i++;return $s;}}